package com.autoops.execution.preflight;import com.autoops.credential.repository.CredentialRepository;import com.autoops.credential.service.CredentialCryptoService;import com.autoops.execution.entity.PreflightRun;import com.autoops.execution.repository.PreflightRunRepository;import com.autoops.infrastructure.remote.RemoteClient;import com.autoops.machine.repository.MachineRepository;import org.springframework.stereotype.Service;import java.time.Instant;@Service public class PreflightService{private final MachineRepository machines;private final CredentialRepository credentials;private final CredentialCryptoService crypto;private final RemoteClient remote;private final PreflightRunRepository repo;public PreflightService(MachineRepository m,CredentialRepository c,CredentialCryptoService x,RemoteClient r,PreflightRunRepository p){machines=m;credentials=c;crypto=x;remote=r;repo=p;}public PreflightRun run(Long machineRunId,Long machineId,Long credentialId){var p=new PreflightRun();p.setMachineRunId(machineRunId);p.setStartedAt(Instant.now());p.setStatus("RUNNING");repo.save(p);var m=machines.findById(machineId).orElseThrow();var c=credentials.findById(credentialId).orElseThrow();String pw=crypto.decrypt(c.getEncryptedPassword(),c.getEncryptionIv());var result=remote.test(m.getHostname(),m.getSshPort(),c.getUsername(),pw);p.setSshStatus(result.success()?"SUCCESS":"FAILED");p.setAuthenticationStatus(result.success()?"SUCCESS":"FAILED");boolean rhel=m.getOperatingSystem()!=null&&m.getOperatingSystem().toLowerCase().contains("rhel");p.setOsStatus(rhel?"SUCCESS":"FAILED");p.setStatus(result.success()&&rhel?"SUCCESS":"FAILED");if(!result.success())p.setFailureReason(result.stderr());p.setFinishedAt(Instant.now());return repo.save(p);}}
